// Spec returns the specification for the named tool if present.
func Spec(name tools.Ident) (tools.ToolSpec, bool) {
	switch name {
	case Join:
		return newSpecJoin(), true
	case Leave:
		return newSpecLeave(), true
	case Read:
		return newSpecRead(), true
	case Send:
		return newSpecSend(), true
	case Who:
		return newSpecWho(), true
	default:
		return tools.ToolSpec{}, false
	}
}

// MetadataByName returns policy metadata for the named tool if present.
func MetadataByName(name tools.Ident) (policy.ToolMetadata, bool) {
	switch name {
	case Join:
		return policy.ToolMetadata{
			ID:          Join,
			Title:       "Join",
			Description: "Subscribe to (or create) #channels and read their topic and recent tail.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		}, true
	case Leave:
		return policy.ToolMetadata{
			ID:          Leave,
			Title:       "Leave",
			Description: "Unsubscribe from #channels.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		}, true
	case Read:
		return policy.ToolMetadata{
			ID:          Read,
			Title:       "Read",
			Description: "Read unread messages (omit 'from' for all subscriptions + DMs; set 'wait_sec' to block).",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		}, true
	case Send:
		return policy.ToolMetadata{
			ID:          Send,
			Title:       "Send",
			Description: "Send a message to @agent or #channel; also drains and returns your unread messages.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		}, true
	case Who:
		return policy.ToolMetadata{
			ID:          Who,
			Title:       "Who",
			Description: "List active participants (@agent), channels (#channel), and your unread message counts.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		}, true
	default:
		return policy.ToolMetadata{}, false
	}
}

// cloneStringMap gives each returned specification ownership of its generated
// field metadata.
func cloneStringMap(source map[string]string) map[string]string {
	if source == nil {
		return nil
	}
	cloned := make(map[string]string, len(source))
	for key, value := range source {
		cloned[key] = value
	}
	return cloned
}
